import pyomo.environ as pyo

DATA = {
    "aircraft": [0, 1, 2, 3, 4, 5],
    "target": {0: 250, 1: 210, 2: 285, 3: 18, 4: 160, 5: 282},
    "earliest": {0: 221, 1: 179, 2: 268, 3: 0, 4: 131, 5: 265},
    "latest": {0: 281, 1: 239, 2: 300, 3: 36, 4: 191, 5: 300},
    "early_rate": {0: 72, 1: 81, 2: 46, 3: 78, 4: 40, 5: 60},
    "late_rate": {0: 59, 1: 40, 2: 34, 3: 24, 4: 80, 5: 14},
    # separation[i][j] = min time gap required if i lands immediately before j
    "separation": {
        0: {1: 15, 2: 15, 3: 15, 4: 15, 5: 15},
        1: {0: 15, 2: 15, 3: 15, 4: 15, 5: 15},
        2: {0: 15, 1: 15, 3: 15, 4: 15, 5: 15},
        3: {0: 15, 1: 15, 2: 15, 4: 15, 5: 15},
        4: {0: 15, 1: 15, 2: 15, 3: 15, 5: 15},
        5: {0: 15, 1: 15, 2: 15, 3: 15, 4: 15},
    },
    "big_m": 500,
}


def build_model(data=None):
    d = data or DATA
    A = d["aircraft"]
    M = d["big_m"]

    model = pyo.ConcreteModel()

    model.A = pyo.Set(initialize=A, ordered=True)
    model.Pairs = pyo.Set(
        initialize=[(i, j) for i in A for j in A if i != j], dimen=2
    )
    model.OrderPairs = pyo.Set(
        initialize=[(i, j) for i in A for j in A if i < j], dimen=2
    )

    def land_bounds(m, i):
        return (d["earliest"][i], d["latest"][i])

    model.land = pyo.Var(model.A, domain=pyo.Reals, bounds=land_bounds)
    model.early = pyo.Var(model.A, domain=pyo.NonNegativeReals)
    model.late = pyo.Var(model.A, domain=pyo.NonNegativeReals)
    model.before = pyo.Var(model.Pairs, domain=pyo.Binary)

    def obj_rule(m):
        return sum(
            d["early_rate"][i] * m.early[i] + d["late_rate"][i] * m.late[i]
            for i in m.A
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def deviation_rule(m, i):
        return m.land[i] == d["target"][i] + m.late[i] - m.early[i]

    model.deviation = pyo.Constraint(model.A, rule=deviation_rule)

    def order_rule(m, i, j):
        return m.before[i, j] + m.before[j, i] == 1

    model.order = pyo.Constraint(model.OrderPairs, rule=order_rule)

    def sep_rule(m, i, j):
        return m.land[j] >= m.land[i] + d["separation"][i][j] - M * (
            1 - m.before[i, j]
        )

    model.separation = pyo.Constraint(model.Pairs, rule=sep_rule)

    return model


